import { describe, it, expect } from 'vitest'
import Page from './app/page'
import { CardStats } from './app/CardStats'
import { RevenueChart } from './app/RevenueChart'
import { LatestInvoices } from './app/LatestInvoices'
import { Suspense } from 'react'

describe('Dashboard Page', () => {
  it('renders Page without awaiting data fetching at top level', () => {
    // Mock fetch so it doesn't actually hit the network
    const originalFetch = global.fetch
    global.fetch = () => new Promise(() => {}) // never resolves

    try {
      const element = Page()
      expect(element).toBeDefined()
      expect(element.type).toBe('main')
    } finally {
      global.fetch = originalFetch
    }
  })

  it('contains Suspense boundaries in Page', () => {
    const originalFetch = global.fetch
    global.fetch = () => new Promise(() => {})

    try {
      const element = Page()
      const children = Array.isArray(element.props.children)
        ? element.props.children
        : [element.props.children]

      const suspenseChildren = children.filter((c: any) => c && c.type === Suspense)
      expect(suspenseChildren.length).toBeGreaterThan(0)
    } finally {
      global.fetch = originalFetch
    }
  })

  it('renders CardStats with props directly', () => {
    const el = CardStats({ totalRevenue: 1000, totalInvoices: 5 })
    expect(el).toBeDefined()
  })

  it('renders RevenueChart with props directly', () => {
    const el = RevenueChart({ revenue: [{ month: 'Jan', amount: 100 }] })
    expect(el).toBeDefined()
  })

  it('renders LatestInvoices with props directly', () => {
    const el = LatestInvoices({ invoices: [{ id: '1', name: 'Alice', amount: 50 }] })
    expect(el).toBeDefined()
  })
})

