import { use } from 'react'

export function CardStats({
  totalRevenue,
  totalInvoices,
  dataPromise,
}: {
  totalRevenue?: number | Promise<number>
  totalInvoices?: number | Promise<number>
  dataPromise?: Promise<{ totalRevenue: number; totalInvoices: number }>
}) {
  let resolvedRevenue = totalRevenue
  let resolvedInvoices = totalInvoices

  if (dataPromise) {
    const data = use(dataPromise)
    resolvedRevenue = data.totalRevenue
    resolvedInvoices = data.totalInvoices
  }

  if (resolvedRevenue && typeof (resolvedRevenue as any).then === 'function') {
    resolvedRevenue = use(resolvedRevenue as Promise<number>)
  }
  if (resolvedInvoices && typeof (resolvedInvoices as any).then === 'function') {
    resolvedInvoices = use(resolvedInvoices as Promise<number>)
  }

  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${resolvedRevenue?.toLocaleString()}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{resolvedInvoices}</p>
      </div>
    </div>
  )
}

