  totalRevenue?: number | Promise<number>
  totalInvoices?: number | Promise<number>
  dataPromise?: Promise<{ totalRevenue: number; totalInvoices: number }>
}) {
  let resolvedRevenue: number | undefined
  let resolvedInvoices: number | undefined

