import { Suspense, use } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

async function getDashboardData(): Promise<DashboardData> {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

function CardStatsWrapper({ dataPromise }: { dataPromise: Promise<DashboardData> }) {
  const data = use(dataPromise)
  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

function RevenueChartWrapper({ dataPromise }: { dataPromise: Promise<DashboardData> }) {
  const data = use(dataPromise)
  return <RevenueChart revenue={data.revenue} />
}

function LatestInvoicesWrapper({ dataPromise }: { dataPromise: Promise<DashboardData> }) {
  const data = use(dataPromise)
  return <LatestInvoices invoices={data.invoices} />
}

export default function Page() {
  const dataPromise = getDashboardData()

  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<div>Loading stats...</div>}>
        <CardStatsWrapper dataPromise={dataPromise} />
      </Suspense>
      <Suspense fallback={<div>Loading revenue...</div>}>
        <RevenueChartWrapper dataPromise={dataPromise} />
      </Suspense>
      <Suspense fallback={<div>Loading invoices...</div>}>
        <LatestInvoicesWrapper dataPromise={dataPromise} />
      </Suspense>
    </main>
  )
}

